입력 args: {rows: [원청구행]}
출력 value: {items: [{invoice_id, asset_id, amount, raw}]}
- asset_id: 원행 asset_id가 null이 아니면 그 값, 아니면 machine (둘 다 없으면 null)
- amount: 원행 amount(정수) 또는 fee 문자열('₩12,345', 'KRW 12,345', '12345')을 원 단위 정수로
- 금액이 없거나 정수로 해석되지 않으면 전체 호출을 실패시킨다 (0으로 바꾸지 않음)
"""
import json
import re
import sys

PROTOCOL = "ibl-script/2"
FEE_RE = re.compile(r"^\s*(?:₩|KRW)?\s*(\d{1,3}(?:,\d{3})+|\d+)\s*$")


def parse_amount(row):
    if "amount" in row and row["amount"] is not None:
        value = row["amount"]
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError(f"amount가 정수가 아님: {value!r}")
        return value
    if "fee" in row and row["fee"] is not None:
        fee = row["fee"]
        if not isinstance(fee, str):
            raise ValueError(f"fee가 문자열이 아님: {fee!r}")
        match = FEE_RE.match(fee)
        if not match:
            raise ValueError(f"fee 형식을 해석할 수 없음: {fee!r}")
        return int(match.group(1).replace(",", ""))
    raise ValueError("amount와 fee가 모두 없음")


def normalize(rows):
    items, errors = [], []
    for index, row in enumerate(rows):
        if not isinstance(row, dict):
            errors.append(f"rows[{index}]: 객체가 아님")
            continue
        try:
            amount = parse_amount(row)
        except ValueError as exc:
            errors.append(f"rows[{index}] invoice_id={row.get('invoice_id')!r}: {exc}")
            continue
        asset_id = row.get("asset_id")
        if asset_id is None:
            asset_id = row.get("machine")
        items.append({"invoice_id": row.get("invoice_id"), "asset_id": asset_id,
                      "amount": amount, "raw": row})
    return items, errors


def main():
    request = json.loads(sys.stdin.read() or "{}")
    args = request.get("args", {}) if request.get("protocol") == PROTOCOL else request
    rows = args.get("rows")
    if not isinstance(rows, list):
        out = {"protocol": PROTOCOL, "ok": False, "error": "rows는 목록이어야 함"}
    else:
        items, errors = normalize(rows)
        if errors:
            shown = errors[:20]
            more = f" 외 {len(errors) - len(shown)}건" if len(errors) > len(shown) else ""
            out = {"protocol": PROTOCOL, "ok": False,
                   "error": f"금액 해석 실패 {len(errors)}건: " + "; ".join(shown) + more}
        else:
            out = {"protocol": PROTOCOL, "ok": True, "value": {"items": items}}
    sys.stdout.write(json.dumps(out, ensure_ascii=False, allow_nan=False))


if __name__ == "__main__":
    main()

